def run_pair(series, cn, dn):
    c, d = series[cn], series[dn]
    results = {}
    results["naive_xcorr"] = naive_xcorr(c, d, cn, dn)
    results["diff_xcorr"] = diff_xcorr(c, d, cn, dn)
    results["threshold_onset"] = threshold_onset(c, d, cn, dn)
    # forward: canary -> downstream (x=canary causes y=downstream)
    results["perm_granger_fwd"] = perm_granger(orient(c, cn), orient(d, dn),
